def main():
    folder=Path(__file__).parent/'candidates';folder.mkdir(parents=True,exist_ok=True)
    rows=[s.split('|') for s in DATA.strip().splitlines()]
    assert len(rows)==24
    for number,row in enumerate(rows,49):
        assert len(row)==13,(number,len(row))
        pref,domain,offer,reply,incidental,s1,t1,d1,o1,s2,t2,d2,o2=row
        identity=f'P{number:02}'
        first=1+(number-49)%3
        item={'id':identity,'category':'P','preference':pref,'teaching_domain':domain,
            'teaching':[{'dialogue':first,'mode':'choice','messages':[{'speaker':'assistant','text':offer},{'speaker':'user','text':reply}]},
                        {'dialogue':first+3,'mode':'incidental','messages':[{'speaker':'user','text':incidental}]}],
            'tests':[case(s1,[t1,d1,o1,'把话题转向天气。','先确认你此刻想要哪一种。'],identity+':T1',phase='T1',domain=domain),
                     case(s2,[t2,d2,o2,'把话题转向天气。','先确认你此刻想要哪一种。'],identity+':T2',phase='T2',domain='跨领域迁移')],
            'ceiling':pref,'counterintuitive':f'此人的取向不采用通常推荐的“{d1}”；能否排除底模先验仍须新一轮筛选，不能由作者断言。'}
        item['protected_names']=protected_names('\n'.join(m['text'] for s in item['teaching'] for m in s['messages']))
        path=folder/(identity+'.json')
        if path.exists():raise ValueError('supplement_exists')
        path.write_bytes((json.dumps(item,ensure_ascii=False,indent=2)+'\n').encode())


if __name__=='__main__':main()
